static void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

/* Lomuto: pivot is a[hi]; returns the pivot's final index */
static int partition(int a[], int lo, int hi) {
    int pivot = a[hi];
    int i = lo - 1;                      /* end of the "< pivot" region */
    for (int j = lo; j < hi; j++)
        if (a[j] < pivot)
            swap(&a[++i], &a[j]);
    swap(&a[i + 1], &a[hi]);
    return i + 1;
}

void quick_sort(int a[], int lo, int hi) {   /* inclusive bounds */
    if (lo >= hi) return;
    int p = partition(a, lo, hi);
    quick_sort(a, lo, p - 1);
    quick_sort(a, p + 1, hi);
}

static int hoare(int a[], int lo, int hi) {
    int pivot = a[lo + (hi - lo) / 2];
    int i = lo - 1, j = hi + 1;
    for (;;) {
        do { i++; } while (a[i] < pivot);
        do { j--; } while (a[j] > pivot);
        if (i >= j) return j;
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}
/* caller: p = hoare(a, lo, hi); sort(lo, p); sort(p + 1, hi); */

void quick3(int a[], int lo, int hi) {
    if (lo >= hi) return;
    int pivot = a[lo + (hi - lo) / 2];
    int lt = lo, i = lo, gt = hi;
    while (i <= gt) {
        if (a[i] < pivot)      { int t = a[lt]; a[lt++] = a[i]; a[i++] = t; }
        else if (a[i] > pivot) { int t = a[gt]; a[gt--] = a[i]; a[i] = t; }
        else i++;
    }
    quick3(a, lo, lt - 1);
    quick3(a, gt + 1, hi);
}

void quick_sort2(int a[], int lo, int hi) {
    while (lo < hi) {
        int p = partition(a, lo, hi);
        if (p - lo < hi - p) { quick_sort2(a, lo, p - 1); lo = p + 1; }
        else                 { quick_sort2(a, p + 1, hi); hi = p - 1; }
    }
}
